FILE = "awar-odhiang-model-of-the-year.html"
TITLE = "Awar Odhiang: from Pugnido to Model of the Year"
TAG = "Flavor Fashion"
H1 = "Awar Odhiang: from Pugnido to Model of the Year"
DEK = "Born in a refugee camp in Ethiopia, raised on the Canadian prairie, scouted in an Old Navy. How the model who closed Chanel became the British Fashion Council's Model of the Year 2026."
META = "Flavor Fashion · 5 Nov 2026 · 5 min read"
LEAD = ("img/ao-cover.jpg", "Awar Odhiang at the 2026 Met Gala", "@awarodhiang / Instagram", "Photo")

IG = "@awarodhiang / Instagram"

BODY = [
("p", "On 4 November the British Fashion Council announced that Awar Odhiang will be honoured as Model of the Year at The Fashion Awards 2026. She receives it at the Royal Albert Hall in London on Monday, 30 November."),
("p", "For most people outside fashion, her name arrived in October 2025, in one joyful walk at Chanel. But the story that got her there starts much further from Paris, in a refugee camp in western Ethiopia."),

("h2", "01 · Where it started", "From Pugnido to ", "Moose Jaw"),
("p", "Odhiang was born in the Pugnido refugee camp in Ethiopia. Her parents are Anyuak and had fled the civil war in South Sudan before she was born."),
("p", "In 2002, when she was about two, a church sponsored the family's move to Canada. They settled in Moose Jaw, a small prairie town in Saskatchewan. She has spoken about how out of place she felt there growing up, describing herself as an outcast."),
("img", "img/ao-portrait.jpg", "Awar Odhiang", IG),

("h2", "02 · The scouting", "Discovered in ", "Calgary"),
("p", "At 16 she moved with her family to Calgary. A year later, while working at an Old Navy store in the city, she was spotted and signed to Mode Models, the Calgary agency that became her mother agency."),
("p", "In January 2020 she left Canada for Italy to model, just weeks before the pandemic shut the world down."),
("img", "img/ao-hermes.jpg", "Walking for Hermès, Spring-Summer 2023, Paris", IG),

("h2", "03 · The groundwork", "Five years of ", "groundwork"),
("p", "The industry knew her well before the internet did. Over the next five years she fronted Saint Laurent campaigns and walked for houses including Hermès, Bottega Veneta and Schiaparelli."),
("p", "Models.com added her to its Top 50 and named her a Model of the Year nominee in 2024. In October that year she also made her Victoria's Secret Fashion Show debut. Her post afterwards opened simply: \"Mama, I'm an Angel.\""),
("duo", [("img/ao-ysl.jpg", "Saint Laurent Pre-Fall 2024"), ("img/ao-vs.jpg", "Victoria's Secret Fashion Show 2024")]),

("h2", "04 · The finale", "Closing ", "Chanel"),
("p", "In October 2025, Matthieu Blazy showed his first collection as Chanel's creative director, and Odhiang closed it. She came out in an oversized white shirt and a skirt of multicoloured silk feathers."),
("p", "Closing models are usually expected to walk with a straight face. She smiled, clapped and spun, then ran to hug Blazy at the end. She later told Vogue it wasn't planned: Blazy had told her the moment was hers, and she simply did what she does."),
("p", "Clips of the walk spread far beyond fashion. It also put her in rare company: she became only the third Black model to close a Chanel show, after Alek Wek in 2004 and Adut Akech in 2018."),
("img", "img/ao-chanel.jpg", "In Chanel's Fall-Winter 2026 campaign", IG),

("h2", "05 · 2026", "Schiaparelli, Vogue Italia, ", "the Met"),
("p", "The year that followed has been hers. In January she won the industry vote for Models.com's Model of the Year, and closed Daniel Roseberry's spring couture show for Schiaparelli in a feathered jacket."),
("p", "In February she was on the cover of Vogue Italia. In May she attended her first Met Gala as Chanel's guest, wearing a beaded dress from the house's spring 2026 haute couture collection."),
("img", "img/ao-schiaparelli.jpg", "Closing Schiaparelli Haute Couture Spring 2026", IG),

("h2", "06 · The honour", "Model of the ", "Year"),
("p", "The Fashion Awards' Model of the Year recognises a model whose impact has defined the past year. In its announcement, the British Fashion Council pointed to her presence and energy since the Chanel finale, and to the standout moments she has been part of since."),
("quote", "To be recognised as Model of the Year is an incredible honour.", "Awar Odhiang"),
("p", "She follows Anok Yai, the 2025 winner, which means the award has gone to a model of South Sudanese heritage two years in a row."),
("img", "img/ao-lv.jpg", "Awar Odhiang for Louis Vuitton", IG),
("p", "On 30 November she'll walk into the Royal Albert Hall as one of the faces of fashion's year."),
]

